// Minimal faithful replica of the Python argparse behavior used by the
// original program: long options only, type 'str' | 'int', required flags,
// -h/--help, GNU-style prefix abbreviation, argparse error/exit semantics.
import { basename } from 'node:path';

// Python argparse's _negative_number_matcher.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
// Python int() literal: optional sign, digits, single underscores between digits.
const INT_LITERAL = /^[+-]?\d+(_\d+)*$/;

export class ArgumentParser {
  constructor({ prog } = {}) {
    this.prog = prog !== undefined ? prog : basename(process.argv[1] || 'program');
    this._args = []; // { flag, dest, type, required, metavar } in definition order
  }

  addArgument(flag, { type = 'str', required = false } = {}) {
    const dest = flag.replace(/^-+/, '');
    this._args.push({ flag, dest, type, required, metavar: dest.toUpperCase() });
  }

  _usage() {
    const parts = ['[-h]'];
    for (const a of this._args) {
      const piece = `${a.flag} ${a.metavar}`;
      parts.push(a.required ? piece : `[${piece}]`);
    }
    return `usage: ${this.prog} ${parts.join(' ')}`;
  }

  _helpText() {
    const lines = [
      this._usage(),
      '',
      'options:',
      '  -h, --help  show this help message and exit',
    ];
    for (const a of this._args) lines.push(`  ${a.flag} ${a.metavar}`);
    return lines.join('\n') + '\n';
  }

  _printHelpAndExit() {
    process.stdout.write(this._helpText());
    process.exit(0);
  }

  _error(msg) {
    process.stderr.write(this._usage() + '\n');
    process.stderr.write(`${this.prog}: error: ${msg}\n`);
    process.exit(2);
  }

  // A token is option-like when it starts with '-', is more than one char,
  // and does not look like a negative number. Bare '-' is value-like.
  _isOptionLike(token) {
    return token.length > 1 && token.startsWith('-') && !NEGATIVE_NUMBER.test(token);
  }

  // Resolve a long option name (no '=' part) exactly or by unambiguous prefix.
  // Returns the arg definition, 'help', or null for unknown options.
  _resolve(name) {
    const longOpts = ['--help', ...this._args.map((a) => a.flag)];
    const exact = longOpts.includes(name);
    const matches = exact ? [name] : longOpts.filter((o) => o.startsWith(name));
    if (matches.length === 0) return null;
    if (matches.length > 1) {
      this._error(`ambiguous option: ${name} could match ${matches.join(', ')}`);
    }
    const resolved = matches[0];
    return resolved === '--help'
      ? 'help'
      : this._args.find((a) => a.flag === resolved);
  }

  _convert(a, raw) {
    if (a.type === 'int') {
      const stripped = raw.trim();
      if (!INT_LITERAL.test(stripped)) {
        this._error(`argument ${a.flag}: invalid int value: '${raw}'`);
      }
      return parseInt(stripped.replace(/_/g, ''), 10);
    }
    return raw;
  }

  parseArgs(argv) {
    const result = {};
    const extras = [];
    const seen = new Set();
    let i = 0;
    while (i < argv.length) {
      const token = argv[i];
      if (token === '--') {
        // End-of-options separator: everything after is positional.
        extras.push(...argv.slice(i + 1));
        break;
      }
      if (token.startsWith('--')) {
        const eq = token.indexOf('=');
        const name = eq === -1 ? token : token.slice(0, eq);
        const explicit = eq === -1 ? undefined : token.slice(eq + 1);
        const match = this._resolve(name);
        if (match === 'help') {
          if (explicit !== undefined) {
            this._error(`argument -h/--help: ignored explicit argument '${explicit}'`);
          }
          this._printHelpAndExit();
        }
        if (match === null) {
          extras.push(token);
          i += 1;
          continue;
        }
        let raw;
        if (explicit !== undefined) {
          raw = explicit;
        } else if (i + 1 < argv.length && !this._isOptionLike(argv[i + 1])) {
          raw = argv[i + 1];
          i += 1;
        } else {
          this._error(`argument ${match.flag}: expected one argument`);
        }
        result[match.dest] = this._convert(match, raw);
        seen.add(match.dest);
      } else if (token === '-h') {
        this._printHelpAndExit();
      } else {
        // Unknown short option, positional, or bare '-'.
        extras.push(token);
      }
      i += 1;
    }
    const missing = this._args
      .filter((a) => a.required && !seen.has(a.dest))
      .map((a) => a.flag);
    if (missing.length > 0) {
      this._error(`the following arguments are required: ${missing.join(', ')}`);
    }
    if (extras.length > 0) {
      this._error(`unrecognized arguments: ${extras.join(' ')}`);
    }
    return result;
  }
}

